codeExample:
const list = [10, 20, NaN, 40];

// 1. Boolean check
console.log(list.includes(20)); // true

// 2. NaN lookup (indexOf fails, includes succeeds)
console.log(list.indexOf(NaN));  // -1
console.log(list.includes(NaN)); // true

// 3. fromIndex offset
console.log(list.includes(10, 1)); // false (starts scanning from index 1)

