// 1. Chaining comparison
const r1 = 2 ** 3 ** 2; // 512
const r2 = Math.pow(2, Math.pow(3, 2)); // 512

// 2. BigInt compatibility
const big = 2n ** 32n;
console.log(big); // 4294967296n

// Math.pow(2n, 32n) -> TypeError

// 3. Unary negation syntax rule
// console.log(-2 ** 2); // SyntaxError: Unparenthesized unary expression can't appear on the LHS of '**'
console.log((-2) ** 2); // 4
console.log(-(2 ** 2)); // -4

