codeExample:
const letters = ['a', 'b', 'c', 'd', 'e'];

console.log(letters.includes('c', 2));  // true (starts at index 2)
console.log(letters.includes('a', 1));  // false (starts at index 1)

// Negative fromIndex (5 + (-2) = index 3)
console.log(letters.includes('d', -2)); // true
console.log(letters.includes('a', -2)); // false

// fromIndex >= length
console.log(letters.includes('a', 10)); // false

