// Right-associative evaluation:
console.log(2 ** 3 ** 2); // 512
// Equivalent to:
console.log(2 ** (3 ** 2)); // 2 ** 9 = 512

// To enforce left-to-right, use grouping:
console.log((2 ** 3) ** 2); // 8 ** 2 = 64

// Precedence with multiplication:
console.log(2 * 3 ** 2); // 18 (2 * 9, not 6 ** 2)

