const roles = ['admin', 'editor', 'viewer'];

// Buggy legacy pattern (index 0 is falsy!):
if (roles.indexOf('admin')) { // evaluates to 0, which is FALSE!
  // Never executes for 'admin'!
}

// Safe legacy pattern:
if (roles.indexOf('admin') !== -1) {
  console.log('Access granted');
}

// Modern, clean, bug-free ES7 pattern:
if (roles.includes('admin')) {
  console.log('Access granted');
}

